begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
select extensions.is((select count(*)::int from pg_tables t where schemaname='public' and tablename<>'forma_connection_checks' and not exists(select 1 from pg_policies p where p.schemaname=t.schemaname and p.tablename=t.tablename and p.policyname='beta_members_only')),0,'every Fontex table retains the beta restriction');
insert into fontex_beta.invitations(email) values ('beta-admin@example.invalid'),('beta-user@example.invalid'),('beta-other@example.invalid');
select extensions.lives_ok($$insert into auth.users(id,email) values('be7a0000-0000-4000-8000-000000000099','uninvited@example.invalid')$$,'registration is open without an administrator invitation');
select extensions.is(fontex_beta.allowed('be7a0000-0000-4000-8000-000000000099'),false,'unconfirmed public registration cannot access remote resources');
insert into auth.users(id,email,raw_user_meta_data) values
('be7a0000-0000-4000-8000-000000000001','beta-admin@example.invalid','{}'),
('be7a0000-0000-4000-8000-000000000002','beta-user@example.invalid','{"is_admin":true,"beta":true}'),
('be7a0000-0000-4000-8000-000000000003','beta-other@example.invalid','{}');
insert into fontex_ai.admins(user_id) values('be7a0000-0000-4000-8000-000000000001');
select extensions.is(fontex_beta.allowed('be7a0000-0000-4000-8000-000000000002'),false,'an invitation without confirmed email does not enable remote access');
update auth.users set email_confirmed_at=now() where id::text like 'be7a0000-%';
select extensions.is((select count(*)::int from fontex_beta.members where user_id::text like 'be7a%'),4,'public and invited signups both become members');
select extensions.is((select enabled from fontex_beta.invitations where email='beta-user@example.invalid'),false,'signup consumes its invitation');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"be7a0000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.is((public.get_beta_access_status()->>'allowed')::boolean,true,'participant can check own membership');
select extensions.throws_ok($$select public.admin_invite_beta('intruder@example.invalid')$$,'42501',null,'metadata cannot grant invitation privileges');
select extensions.throws_ok($$select public.admin_set_beta_ai_enabled(false)$$,'42501',null,'normal user cannot pause AI');
select extensions.ok(not has_table_privilege('authenticated','fontex_beta.members','insert'),'membership has no direct client writes');
select extensions.ok(not has_function_privilege('authenticated','public.reserve_canvas_ai_request(uuid,uuid,text,integer)','execute'),'clients cannot reserve quota with a forged user id');
reset role;
update fontex_beta.members set active=false where user_id='be7a0000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"be7a0000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.is((public.get_beta_access_status()->>'allowed')::boolean,false,'revocation is visible without refreshing JWT');
select extensions.is((select count(*)::int from public.profiles),0,'revoked users lose table access through restrictive RLS');
select extensions.throws_ok($$select public.get_ai_credit_status()$$,'42501','beta_invitation_required','direct credit RPC calls cannot bypass membership');
select extensions.throws_ok($$select public.create_workspace('Blocked','Blocked',null)$$,'42501','beta_invitation_required','direct definer RPC writes cannot bypass membership');
select set_config('request.path','/rpc/get_ai_credit_status',true);
select extensions.throws_ok($$select public.check_beta_request()$$,'42501','beta_invitation_required','API guard also rejects credit and other definer RPCs');
select set_config('request.method','GET',true);
select set_config('request.headers','{"accept-profile":"forma"}',true);
select extensions.lives_ok($$select public.check_beta_request()$$,'shared forma reads remain independent of Fontex membership');
select set_config('request.method','POST',true);
select extensions.throws_ok($$select public.check_beta_request()$$,'42501','beta_invitation_required','a forged read profile cannot bypass a public POST guard');
select set_config('request.headers','{"content-profile":"forma"}',true);
select extensions.lives_ok($$select public.check_beta_request()$$,'shared forma writes remain independent of Fontex membership');
select set_config('request.method','GET',true);
select extensions.throws_ok($$select public.check_beta_request()$$,'42501','beta_invitation_required','a forged write profile cannot bypass a public GET guard');
select set_config('request.headers','{}',true);
select set_config('request.path','/rpc/get_beta_access_status',true);
select extensions.lives_ok($$select public.check_beta_request()$$,'membership status remains accessible to a blocked account');
select set_config('request.jwt.claims','{"sub":"be7a0000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select public.admin_invite_beta('beta-user@example.invalid');
reset role;
select extensions.is((select active from fontex_beta.members where user_id='be7a0000-0000-4000-8000-000000000002'),true,'admin re-enables an existing account by UUID');
set local role authenticated;
select public.admin_invite_beta('future@example.invalid');
reset role;
insert into auth.users(id,email) values('be7a0000-0000-4000-8000-000000000004','future@example.invalid');
update auth.users set email_confirmed_at=now() where id='be7a0000-0000-4000-8000-000000000004';
select extensions.is((select count(*)::int from fontex_beta.members where user_id='be7a0000-0000-4000-8000-000000000004'),1,'administrator invitation admits a future signup');
update fontex_beta.runtime_limits set max_user_hour=2,max_reserved_tokens_day=1000;
set local role service_role;
select extensions.is((public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000002','be7a0001-0000-4000-8000-000000000001','chat',100)->>'allowed')::boolean,true,'chat reserves usage without spending credits');
select extensions.is(public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000002',gen_random_uuid(),'chat',100)->>'reason','request_busy','same account cannot run concurrent chat/build');
select public.finish_canvas_ai_request('be7a0001-0000-4000-8000-000000000001');
select public.finish_canvas_ai_request('be7a0001-0000-4000-8000-000000000001');
select extensions.is((public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000002','be7a0001-0000-4000-8000-000000000002','build',100)->>'allowed')::boolean,true,'completion releases the concurrent slot idempotently');
select public.finish_canvas_ai_request('be7a0001-0000-4000-8000-000000000002');
select extensions.is(public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000002',gen_random_uuid(),'chat',100)->>'reason','user_rate_limit','rolling hour counts both modes and completed calls');
select extensions.is(public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000003',gen_random_uuid(),'chat',801)->>'reason','global_budget','global budget includes previous completed requests');
reset role;
update fontex_beta.runtime_limits set ai_enabled=false;
set local role service_role;
select extensions.is(public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000003',gen_random_uuid(),'chat',1)->>'reason','ai_paused','global pause rejects before provider');
select extensions.is((public.internal_beta_access('be7a0000-0000-4000-8000-000000000003')->>'ai_enabled')::boolean,false,'all AI entrypoints can enforce the same pause');
reset role;
update fontex_beta.runtime_limits set ai_enabled=true,max_global_concurrent=1;
set local role service_role;
select public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000003','be7a0001-0000-4000-8000-000000000003','chat',1);
select extensions.is(public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000004',gen_random_uuid(),'chat',1)->>'reason','global_busy','global concurrent slot applies across users');
reset role;
update fontex_beta.requests set expires_at=now()-interval '1 second' where id='be7a0001-0000-4000-8000-000000000003';
set local role service_role;
select extensions.is((public.reserve_canvas_ai_request('be7a0000-0000-4000-8000-000000000004',gen_random_uuid(),'chat',1)->>'allowed')::boolean,true,'expired interrupted requests release slots');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"be7a0000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into public.visual_scenes(user_id,id,scene)
select auth.uid(),'quota-'||n,jsonb_build_object('id','quota-'||n,'schemaVersion',2,'format','primitive-scene','title','Quota','level','secundaria','updatedAt',now()::text,'variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb) from generate_series(1,100) n;
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values(auth.uid(),'quota-extra','{"id":"quota-extra","schemaVersion":2,"format":"primitive-scene","title":"Quota","level":"secundaria","updatedAt":"now","variables":[],"primitives":[],"conversation":[]}')$$,'54000',null,'scene count quota is enforced in the database');
delete from public.visual_scenes where user_id=auth.uid();
insert into public.visual_scenes(user_id,id,scene)
select auth.uid(),'bytes-'||n,jsonb_build_object('id','bytes-'||n,'schemaVersion',2,'format','primitive-scene','title','Quota','level','secundaria','updatedAt',now()::text,'variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb,'padding',repeat('x',900000)) from generate_series(1,23) n;
select extensions.throws_ok($$insert into public.visual_scenes(user_id,id,scene) values(auth.uid(),'bytes-extra',jsonb_build_object('id','bytes-extra','schemaVersion',2,'format','primitive-scene','title','Quota','level','secundaria','updatedAt',now()::text,'variables','[]'::jsonb,'primitives','[]'::jsonb,'conversation','[]'::jsonb,'padding',repeat('x',900000)))$$,'54000',null,'aggregate byte quota cannot be bypassed with many individually valid rows');
reset role;
set local role anon;
select set_config('request.path','/rpc/get_release_contract',true);
select extensions.lives_ok($$select public.check_beta_request()$$,'public read-only release contract is available without a participant session');
select extensions.is(public.get_release_contract(),'closed-beta-v4','release gate checks an explicit backend contract');
select * from extensions.finish();
rollback;
